def _apply(src, fixes, who):
    for old, new in fixes:
        count = src.count(old)
        if count != 1:
            raise SystemExit("payload_v28: %s, this anchor matches %d times, not once:\n    %s"
                             % (who, count, old.splitlines()[0][:80]))
        src = src.replace(old, new, 1)
    return src


def patch_all(src):
    src = _apply(src, _CAPTURE_PAGE_FIXES, "all.html")
    src = _apply(src, _PAGE_FIXES, "all.html")
    src = _apply(src, _CAPTURE_SERVER_FIXES, "all server")
    return _apply(src, _SERVER_FIXES, "all server")
